<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$adminPage='customers';$adminTitle='مشتریان';$q=text_substr(trim(scalar_string($_GET['q']??'')),0,100);$params=[];$where='';if($q!==''){$where=' WHERE c.phone LIKE ? OR c.full_name LIKE ? OR c.email LIKE ?';$params=['%'.$q.'%','%'.$q.'%','%'.$q.'%'];}$stats="SELECT o.customer_id,COUNT(*) orders_count,COALESCE(SUM(GREATEST(o.total-COALESCE(rf.refunded_amount,0),0)),0) total_spent FROM orders o LEFT JOIN (SELECT order_id,SUM(amount) refunded_amount FROM refund_transactions WHERE status='completed' GROUP BY order_id) rf ON rf.order_id=o.id WHERE o.customer_id IS NOT NULL AND o.order_status<>'cancelled' AND o.payment_status IN ('paid','partially_refunded','refunded') GROUP BY o.customer_id";$stmt=db()->prepare('SELECT c.*,COALESCE(s.orders_count,0) orders_count,COALESCE(s.total_spent,0) total_spent FROM customers c LEFT JOIN ('.$stats.') s ON s.customer_id=c.id'.$where.' ORDER BY c.id DESC LIMIT 500');$stmt->execute($params);$rows=$stmt->fetchAll();require __DIR__.'/partials/header.php';
?>
<div class="admin-title"><h1>مشتریان</h1><span class="muted"><?=fa_number(count($rows))?> مشتری</span></div><form class="filters-admin"><input name="q" value="<?=e($q)?>" placeholder="نام، موبایل یا ایمیل"><button class="btn btn-secondary">جست‌وجو</button></form><div class="table-wrap"><table><thead><tr><th>نام</th><th>اطلاعات ورود</th><th>روش حساب</th><th>سفارش‌ها</th><th>مجموع خرید</th><th>آخرین ورود</th><th>عضویت</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name']?:'ثبت نشده')?></td><td><?=e($r['phone']?:'—')?><br><small><?=e($r['email']?:'—')?></small></td><td><?=!empty($r['google_sub'])?'Google':(!empty($r['password_hash'])?'موبایل/رمز':'کد پیامکی')?></td><td><?=fa_number($r['orders_count'])?></td><td><?=fa_number(format_price($r['total_spent']))?> تومان</td><td><?=e($r['last_login_at']?jalali_format($r['last_login_at']):'—')?></td><td><?=e(jalali_format($r['created_at']))?></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="7">مشتری پیدا نشد.</td></tr><?php endif?></tbody></table></div><?php require __DIR__.'/partials/footer.php';
